const token = fs.readFileSync('/tmp/admin-token.txt', 'utf8').trim();
const [width, height, outPath, path] = process.argv.slice(2);

const tab = await fetch('http://127.0.0.1:9222/json/new?http://localhost:5173/', {
  method: 'PUT',
}).then((r) => r.json());

const ws = new WebSocket(tab.webSocketDebuggerUrl);
let id = 0;
const pending = new Map();
ws.addEventListener('message', (event) => {
  const msg = JSON.parse(event.data);
  if (msg.id && pending.has(msg.id)) {
    pending.get(msg.id)(msg);
    pending.delete(msg.id);
  }
});
const send = (method, params = {}) =>
  new Promise((resolve) => {
    const messageId = ++id;
    pending.set(messageId, resolve);
    ws.send(JSON.stringify({ id: messageId, method, params }));
  });

await new Promise((resolve) => ws.addEventListener('open', resolve));
await send('Page.enable');
await send('Runtime.enable');
await send('Emulation.setDeviceMetricsOverride', {
  width: Number(width),
  height: Number(height),
  deviceScaleFactor: 1,
  mobile: false,
});

await new Promise((resolve) => setTimeout(resolve, 2000));
await send('Runtime.evaluate', {
  expression: `localStorage.setItem('hinga.token', ${JSON.stringify(token)})`,
});
await send('Page.navigate', { url: `http://localhost:5173${path}` });
await new Promise((resolve) => setTimeout(resolve, 4500));

const info = await send('Runtime.evaluate', {
  expression: `JSON.stringify({ h: document.body.scrollHeight, w: document.documentElement.scrollWidth, title: document.title, h1: document.querySelector('h1')?.textContent })`,
  returnByValue: true,
});
console.log(info.result?.result?.value);

const shot = await send('Page.captureScreenshot', { format: 'png', captureBeyondViewport: true });
fs.writeFileSync(outPath, Buffer.from(shot.result.data, 'base64'));
ws.close();
"}}


