const AVATARS = [
  'bg-blush text-rose',
  'bg-sage-soft text-forest',
  'bg-clay-soft text-clay',
  'bg-gold-soft text-gold',
];

const initials = (name = '') =>
  name
    .split(' ')
    .filter(Boolean)
    .slice(0, 2)
    .map((part) => part.charAt(0).toUpperCase())
    .join('');

