{"kind":"tool","id":"eKTkUX2TJsw","toolName":"write_file","input":{"path":"../tmp/addr-test.mjs","instructions":"Test the saved-address picker in checkout via CDP.","content":"import fs from 'node:fs';

const token = fs.readFileSync('/tmp/customer-token.txt', 'utf8').trim();
const t = await fetch('http://127.0.0.1:9222/json/new?http://localhost:5173/', { method: 'PUT' }).then((r) => r.json());
const ws = new WebSocket(t.webSocketDebuggerUrl);
let id = 0;
const pending = new Map();
ws.addEventListener('message', (e) => {
  const m = JSON.parse(e.data);
  if (m.id && pending.has(m.id)) {
    pending.get(m.id)(m);
    pending.delete(m.id);
  }
});
const send = (method, params = {}) =>
  new Promise((resolve) => {
    const n = ++id;
    pending.set(n, resolve);
    ws.send(JSON.stringify({ id: n, method, params }));
  });
const evaluate = async (expression) => {
  const res = await send('Runtime.evaluate', { expression, returnByValue: true, awaitPromise: true });
  return res.result?.result?.value;
};
const wait = (ms) => new Promise((r) => setTimeout(r, ms));

await new Promise((r) => ws.addEventListener('open', r));
await send('Page.enable');
await send('Runtime.enable');
await send('Emulation.setDeviceMetricsOverride', { width: 1440, height: 1400, deviceScaleFactor: 1, mobile: false });
await wait(1200);
await evaluate(`localStorage.setItem('hinga.token', ${JSON.stringify(token)})`);
await send('Page.navigate', { url: 'http://localhost:5173/checkout' });
await wait(4000);

const read = () =>
  evaluate(`JSON.stringify({
    cards: Array.from(document.querySelectorAll('button[aria-pressed]')).map(b => b.innerText.replace(/\\n+/g, ' | ')),
    selected: Array.from(document.querySelectorAll('button[aria-pressed="true"]')).map(b => b.innerText.split('\\n')[0]),
    hasSaved: document.body.innerText.includes('Saved addresses'),
    values: {
      name: document.querySelector('#name')?.value,
      address: document.querySelector('#address')?.value,
      city: document.querySelector('#city')?.value,
      state: document.querySelector('#state')?.value,
      zip: document.querySelector('#zip')?.value,
      country: document.querySelector('#country')?.value,
    },
    totals: document.querySelector('button[type="submit"]')?.innerText,
    overflow: document.documentElement.scrollWidth > document.documentElement.clientWidth,
  })`);

console.log('initial', await read());

await evaluate(`Array.from(document.querySelectorAll('button[aria-pressed]')).find(b => b.innerText.startsWith('Studio'))?.click()`);
await wait(700);
console.log('picked studio', await read());

await evaluate(`Array.from(document.querySelectorAll('button')).find(b => b.innerText.trim() === 'Use a new address')?.click()`);
await wait(700);
console.log('new address', await read());

await evaluate(`Array.from(document.querySelectorAll('button[aria-pressed]')).find(b => b.innerText.startsWith('Home'))?.click()`);
await wait(700);
console.log('picked home', await read());

await evaluate(`(() => {
  const el = document.querySelector('#zip');
  const setter = Object.getOwnPropertyDescriptor(el.constructor.prototype, 'value').set;
  setter.call(el, '00900');
  el.dispatchEvent(new Event('input', { bubbles: true }));
})()`);
await wait(500);
console.log('edited zip', await evaluate(`JSON.stringify({ selected: Array.from(document.querySelectorAll('button[aria-pressed="true"]')).length, zip: document.querySelector('#zip').value, newLink: Array.from(document.querySelectorAll('button')).some(b => b.innerText.trim() === 'Use a new address') })`));

const shot = await send('Page.captureScreenshot', { format: 'png', captureBeyondViewport: false });
fs.writeFileSync('/tmp/addr-desktop.png', Buffer.from(shot.result.data, 'base64'));

await evaluate(`Array.from(document.querySelectorAll('button[aria-pressed]')).find(b => b.innerText.startsWith('Home'))?.click()`);
await wait(500);
await evaluate(`Array.from(document.querySelectorAll('button')).find(b => b.innerText.includes('Place order'))?.click()`);
await wait(4500);
console.log(
  'after submit',
  await evaluate(`JSON.stringify({ path: location.pathname, h1: document.querySelector('h1')?.textContent, body: document.body.innerText.slice(0, 160) })`),
);

ws.close();
"}}


