const tab = tabs.find((t) => t.url.includes('/checkout'));
const ws = new WebSocket(tab.webSocketDebuggerUrl);
let id = 0;
const pending = new Map();
ws.addEventListener('message', (e) => {
  const m = JSON.parse(e.data);
  if (m.id && pending.has(m.id)) {
    pending.get(m.id)(m);
    pending.delete(m.id);
  }
});
const send = (method, params = {}) =>
  new Promise((resolve) => {
    const n = ++id;
    pending.set(n, resolve);
    ws.send(JSON.stringify({ id: n, method, params }));
  });
await new Promise((r) => ws.addEventListener('open', r));
await send('Runtime.enable');
const res = await send('Runtime.evaluate', {
  expression: `JSON.stringify({
    viewport: innerWidth,
    doc: document.documentElement.clientWidth,
    scroll: document.documentElement.scrollWidth,
    body: document.body.scrollWidth,
    offenders: Array.from(document.querySelectorAll('*'))
      .map(el => ({ tag: el.tagName, cls: (el.className || '').toString().slice(0, 70), right: Math.round(el.getBoundingClientRect().right), width: Math.round(el.getBoundingClientRect().width), text: (el.innerText || '').slice(0, 30) }))
      .filter(x => x.right > document.documentElement.clientWidth + 1)
      .slice(0, 12),
  })`,
  returnByValue: true,
});
console.log(res.result?.result?.value);
ws.close();
"}}


